from pathlib import Path
import base64, lzma, hashlib, subprocess, tempfile, json
root=Path(__file__).resolve().parents[1]
source=root / 'EmbyFlowE2_Trailers_20261002_0201.py'
assert hashlib.sha256(source.read_bytes()).hexdigest()=='dd2af2f992fd1c819b2c3719974017cd8d25781d0ecb537bb1619178836a45fa', 'Source checksum mismatch'
with tempfile.TemporaryDirectory() as d:
    p=Path(d)/'plugin.py'; p.write_bytes(source.read_bytes())
    subprocess.run(['patch','--batch','--forward',str(p)],input=lzma.decompress(base64.b64decode('')),check=True)
    data=p.read_bytes()
compile(data, 'plugin.py', 'exec')
assert hashlib.sha256(data).hexdigest()=='01ea0a92517036b0b93047b09442034a9288d3a951877860707d605ff99028ef'
(root / 'EmbyFlowE2_KinoCheck_20261003_0301.py').write_bytes(data)
(root / 'update.json').write_text('{\n  "version": "2026-RCDEV-KINOCHECK-20261003",\n  "build": 2026100301,\n  "channel": "rcdev",\n  "target": "plugin.py",\n  "artifact_type": "plugin_py",\n  "download": "https://raw.githubusercontent.com/keggy6893/EmbyFlowE2-Updates/main/EmbyFlowE2_KinoCheck_20261003_0301.py",\n  "sha256": "01ea0a92517036b0b93047b09442034a9288d3a951877860707d605ff99028ef",\n  "changelog": [\n    "Testupdate: KinoCheck-Trailersuche fuer Filme und Serien, Deutsch oder Englisch",\n    "Vorhandene YouTube-Links pruefen; bei Fehlern KinoCheck mit Titel, Originaltitel und Jahr durchsuchen",\n    "Resolver im Hintergrund vorladen und erfolgreiche Aufloesungen kurz zwischenspeichern",\n    "Playerstart korrigiert: fehlender Hintergrund-Timer blockiert Trailer nicht mehr",\n    "Getestet auf openATV 8.0: Fallout-Serie, Schumacher und KinoCheck-Suche fuer Mission: Impossible - Fallout",\n    "Nicht fuer jeden Titel ist ein passender, abspielbarer Trailer verfuegbar"\n  ]\n}\n',encoding='utf-8')
